<script setup lang="ts">
import {computed} from 'vue';
import type {PeakMapping,ResultUpload,PeakField,SpectrumMetric} from '../peakRecordTypes';
import {TECHNIQUE_LABELS} from '../peakRecordAdapters';
const props=defineProps<{upload:ResultUpload;disabled?:boolean}>();
const mapping=defineModel<PeakMapping>({required:true});
const emit=defineEmits<{change:[];refresh:[]}>();
const columns=computed(()=>props.upload.sheets.find(s=>s.name===mapping.value.sheet)?.columns??[]);
const common=[['sample_id','样品 ID'],['spectrum_id','谱 ID'],['peak_id','峰 ID'],['label','峰名称'],['model','峰形模型']];
const wide=[['position','峰位'],['width','峰宽'],['height','峰高'],['area','积分面积'],['position_se','峰位标准误'],['width_se','峰宽标准误'],['height_se','峰高标准误'],['area_se','面积标准误'],['rmse','RMSE'],['r_squared','R²'],['rss','RSS'],['chi_square','χ²']];
const long=[['parameter','参数名称'],['value','数值'],['unit','单位'],['standard_error','标准误'],['scope','作用层级（spectrum / peak）']];
const roles=computed(()=>[...common,...(mapping.value.layout==='wide'?wide:long)]);
function setColumn(key:string,value:string){if(value==='')delete mapping.value.columns[key];else mapping.value.columns[key]=value;changed();}
function changed(){delete mapping.value.fingerprint;emit('change');}
const units:PeakField[]=['position','width','height','area'];
const unitLabels={position:'峰位单位',width:'峰宽单位',height:'峰高单位',area:'面积单位'};
const metricLabels={rmse:'RMSE 单位（与信号一致）',r_squared:'R² 单位（通常为 1）',rss:'RSS 单位（信号单位的平方）',chi_square:'χ² 单位（按源报告声明）'};
const metricUnits=computed(()=>Object.entries(metricLabels).filter(([k])=>mapping.value.layout==='long'||mapping.value.columns[k]!==undefined));
function setMetricUnit(key:string,value:string){mapping.value.units[key as SpectrumMetric]=value;changed();}
function addAlias(event:Event){const form=event.target as HTMLFormElement;const alias=(form.elements.namedItem('alias')as HTMLInputElement).value.trim();if(alias&&!['__proto__','constructor','prototype'].includes(alias)){mapping.value.parameter_aliases??={};mapping.value.parameter_aliases[alias]='position';form.reset();changed();}}
function addMetadata(event:Event){const form=event.target as HTMLFormElement;const key=(form.elements.namedItem('key')as HTMLInputElement).value.trim();if(key&&!['__proto__','constructor','prototype'].includes(key)){mapping.value.metadata??={};mapping.value.metadata[key]='';form.reset();changed();}}
</script>
<template>
 <fieldset class="peak-mapping" :disabled="disabled"><legend>字段与数量定义</legend>
  <div class="peak-form-grid"><label>表征类型<select v-model="mapping.technique" @change="changed"><option v-for="(label,id) in TECHNIQUE_LABELS" :key="id" :value="id">{{label}}</option></select></label><label>工作表<select v-model="mapping.sheet" @change="changed();emit('refresh')"><option v-for="s in upload.sheets" :key="s.name" :value="s.name">{{s.name}}</option></select></label><label>数据布局<select v-model="mapping.layout" @change="changed"><option value="wide">每行一个峰（宽表）</option><option value="long">每行一个参数（长表）</option></select></label><label>表头行（从 1 开始）<input v-model.number="mapping.header_row" type="number" min="1" @change="changed();emit('refresh')" /></label><label>数据起始行（可留空）<input v-model.number="mapping.data_start_row" type="number" min="1" @change="changed" /></label><label>数据结束行（可留空）<input v-model.number="mapping.data_end_row" type="number" min="1" @change="changed" /></label></div>
  <div class="peak-table-scroll"><table><thead><tr><th>含义</th><th>对应文件列</th></tr></thead><tbody><tr v-for="[key,label] in roles" :key="key"><th><label :for="`peak-map-${upload.upload_id}-${key}`">{{label}}</label></th><td><select :id="`peak-map-${upload.upload_id}-${key}`" :value="mapping.columns[key]??''" @change="setColumn(key,($event.target as HTMLSelectElement).value)"><option value="">未提供／不映射</option><option v-for="c in columns" :key="c" :value="c">{{c}}</option></select></td></tr></tbody></table></div>
  <p class="hint">缺少样品、谱或峰 ID 时会产生技术 ID 并提示复核；不同文件中同名的 p1 不会自动认作同一个物理峰。</p>
  <div class="peak-form-grid"><label v-for="k in units" :key="k">{{unitLabels[k]}}<input v-model="mapping.units[k]" placeholder="如 deg、rad、cm^-1、a.u." @input="changed" /></label><label>峰位定义<select v-model="mapping.position_definition" @change="changed"><option value="unknown">未知</option><option value="two_theta">衍射角 2θ</option><option value="apex">实际峰顶</option><option value="model_position">模型位置参数</option><option value="centroid">质心</option></select></label><label>峰宽定义<select v-model="mapping.width_definition" @change="changed"><option value="unknown">未知，保留原值</option><option value="fwhm">半高全宽 FWHM</option><option value="hwhm">半高半宽 HWHM</option><option value="sigma">Gaussian σ</option></select></label><label>面积定义<select v-model="mapping.area_definition" @change="changed"><option value="unknown">未知</option><option value="total">模型全域积分</option><option value="range">指定区间积分</option></select></label><label>未提供模型列时的峰形<select v-model="mapping.default_model" @change="changed"><option value="unknown">未知</option><option value="gaussian">Gaussian</option><option value="lorentz">Lorentz</option><option value="psd_voigt1">Pseudo-Voigt</option><option value="other">其他</option></select></label></div>
  <div v-if="metricUnits.length" class="peak-form-grid"><label v-for="[key,label] in metricUnits" :key="key">{{label}}<input :value="mapping.units[key as SpectrumMetric]" :data-test="`metric-unit-${key}`" placeholder="留空表示未知；无量纲可填 1" @input="setMetricUnit(key,($event.target as HTMLInputElement).value)" /></label></div>
  <p class="hint">仅在定义和模型足够明确时转换峰宽。面积占比不等于组分含量；未知误差不会填为零。谱级指标的单位按源报告填写，χ² 不自动推定为无量纲。</p>
  <details v-if="mapping.layout==='long'" class="peak-detail"><summary>参数名称别名（可选）</summary><p class="hint">未被自动识别的参数名可在归一化后查看异常，再在下表补充。</p><div v-for="(target,alias) in mapping.parameter_aliases" :key="alias" class="peak-form-grid"><span>{{alias}}</span><select :value="target" @change="mapping.parameter_aliases![alias]=($event.target as HTMLSelectElement).value;changed()"><option v-for="[key,label] in wide" :value="key" :key="key">{{label}}</option></select><button @click.prevent="delete mapping.parameter_aliases![alias];changed()">移除</button></div><form class="peak-inline-actions" @submit.prevent="addAlias"><label>原始参数名<input name="alias" /></label><button type="submit">添加别名</button></form></details>
  <details class="peak-detail"><summary>实验元数据（可用于用户公式）</summary><p class="hint">这里的键值应用到本文件所选记录；例如 temperature、phase、measurement_id。可在公式中绑定元数据并声明单位。</p><div v-for="(v,key) in mapping.metadata" :key="key" class="peak-form-grid"><label>{{key}}<input :value="v" :type="typeof v==='number'?'number':'text'" @input="mapping.metadata![key]=typeof v==='number'?Number(($event.target as HTMLInputElement).value):($event.target as HTMLInputElement).value;changed()" /></label><div class="peak-inline-actions"><button type="button" @click="mapping.metadata![key]=typeof v==='number'?String(v):Number(v)||0;changed()">{{typeof v==='number'?'转为文本':'转为数值'}}</button><button type="button" @click="delete mapping.metadata![key];changed()">移除</button></div></div><form @submit.prevent="addMetadata" class="peak-inline-actions"><label>元数据键<input name="key" /></label><button type="submit">添加元数据</button></form></details>
 </fieldset>
</template>
